import {readFileSync,writeFileSync} from 'node:fs';
import {validateCanonicalLandscape} from './app/src/utils/authoring/canonicalAuthoring.ts';
import {buildApplicabilityCompilation} from './app/scripts/applicabilityCompiler.ts';
import {routeProfiles,evaluateRouteProfile,ownProjectedScopeRows,collectWholeMaterialPrerequisiteClosure} from './app/scripts/generateCurriculumQualityStatus.ts';
const land=JSON.parse(readFileSync('./curricula/DE/Gymnasium/canonical/DE_DEU_S_GYM_CANONICAL_WIRTSCHAFT.de.json','utf8'));
const all=buildApplicabilityCompilation();const report=all.reports.find(r=>r.landscapeId===land.landscapeId)!;
const profile=routeProfiles.find(p=>p.landscapeId===land.landscapeId)!;const route=evaluateRouteProfile(land,profile,{...all,reports:[report]});
const ids=['294f5721-33b8-553d-b62a-32f9a0d28f5c','0d111408-c754-50fa-8cd3-25ec75f6205f'];
const materials=ids.map(id=>{const g=land.goals.find(g=>g.id===id);if(!g)return {id,absent:true};const c=collectWholeMaterialPrerequisiteClosure(land,id);return {id,wholeGoal:g,allMandatoryAtomicPrerequisites:[...c.atomicGoalIds],unresolvedReferences:[...c.unresolvedReferences],actualCompiled:report.goals.find(x=>x.goalId===id),scopes:ownProjectedScopeRows.filter(r=>r.actualTerminalIds.includes(id)).map(r=>({viewPath:r.viewPath,jurisdiction:r.jurisdiction,scopeFilters:r.scopeFilters,closureIssues:r.wholeMaterialPrerequisiteClosureIssues,coverageIssues:r.wholeMaterialCoverageBindingIssues}))};});
const graph=validateCanonicalLandscape(land);if(graph.some(g=>g.severity==='error'))throw new Error(JSON.stringify(graph));
writeFileSync(process.argv[2],JSON.stringify({landscapeId:land.landscapeId,goalCount:land.goals.length,graph,compiler:report.summary,nativeRules:route.rules,newMaterials:materials,conditionalAuthorOnlyNoMaterialRelease:true,allScopeRows:ownProjectedScopeRows},null,2)+'\n');
console.log(JSON.stringify({goalCount:land.goals.length,graphErrors:graph.filter(g=>g.severity==='error').length,compiler:report.summary,rules:route.rules.map(r=>({id:r.id,status:r.status,metrics:r.metrics})),newMaterialIds:ids,conditionalAuthorOnly:true},null,2));
